ssize_t prepare_iovec(struct kiocb *kiocb, int rw, char __user *buf, unsigned long *nr_segs, struct iovec *iovec) {
    ssize_t ret;
    size_t len = kiocb->ki_nbytes;

    if (rw == READ) {
        ret = get_user((unsigned long)buf, (unsigned long __user *)buf);
    } else {
        ret = put_user((unsigned long)buf, (unsigned long __user *)buf);
    }

    if (ret)
        return -EFAULT;

    iovec->iov_base = (void __user *)buf;
    iovec->iov_len = len;
    *nr_segs = 1;

    return 0;
}

